package com.sobrenaturaldirector.spatial.model;
import com.sobrenaturaldirector.domain.StableId;import com.sobrenaturaldirector.spatial.geometry.LocalVec3i;
public final class LocalAnchor {private final String id,sourceId,placementId;private final LocalVec3i position;public LocalAnchor(String id,String source,String placement,LocalVec3i position){this.id=StableId.require(id,"anchorId");this.sourceId=StableId.require(source,"anchorSourceId");this.placementId=StableId.require(placement,"anchorPlacementId");if(position==null)throw new IllegalArgumentException("anchor position");this.position=position;}public String getId(){return id;}public String getSourceId(){return sourceId;}public String getPlacementId(){return placementId;}public LocalVec3i getPosition(){return position;}}
